package io.github.rebrowser.download;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.core.Cancellation;
import java.io.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.*;
/** Actual owned sink methods; SYNTHETIC source and memory provider, not OS URI grants/publication. */
public final class SelectedSaveOutputTest {
 static final class F {final AtomicReference<ComponentGate.SourceView> view=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(this,new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,view::get);final ComponentGate.DataEpochPin pin=gate.captureDataEpoch(gate.requireBusiness());SaveTargetRegistry.OwnedOutput output(OutputStream actual,long max)throws Exception{Constructor<SaveTargetRegistry.OwnedOutput> c=SaveTargetRegistry.OwnedOutput.class.getDeclaredConstructor(OutputStream.class,ComponentGate.DataEpochPin.class,long.class);c.setAccessible(true);return c.newInstance(actual,pin,max);}}
 static ResponseStreamWorker.CopiedStage copy(byte[] bytes)throws Exception{return ResponseStreamWorker.copyOwned(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length,bytes.length,Cancellation.create().requester());}
 static void exact(SaveTargetRegistry.OwnedOutput o,ResponseStreamWorker.CopiedStage expected)throws Throwable{Method m=SaveTargetRegistry.OwnedOutput.class.getDeclaredMethod("requireExactCopyClose",ResponseStreamWorker.CopiedStage.class);m.setAccessible(true);try{m.invoke(o,expected);}catch(InvocationTargetException e){throw e.getCause();}}
 @Test public void exactCompleteBytesAndActualCloseRequired()throws Throwable{F f=new F();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(),3);out.write(new byte[]{1,2,3});ResponseStreamWorker.CopiedStage expected=copy(new byte[]{1,2,3});assertThrows(SecurityException.class,()->exact(out,expected));out.close();exact(out,expected);assertEquals(3,out.bytesWritten());}
 @Test public void correctLengthWrongDigestCannotCreateReadReceipt()throws Throwable{F f=new F();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(),3);out.write(new byte[]{1,2,3});out.close();assertThrows(SecurityException.class,()->exact(out,copy(new byte[]{1,2,4})));}
 @Test public void partialOutputCannotLookComplete()throws Throwable{F f=new F();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(),3);out.write(new byte[]{1,2});out.close();assertThrows(SecurityException.class,()->exact(out,copy(new byte[]{1,2,3})));}
 @Test public void unknownWriteBlocksReadEvenIfProviderLaterCloses()throws Throwable{F f=new F();OutputStream bad=new OutputStream(){public void write(int b)throws IOException{throw new IOException("synthetic provider");}};SaveTargetRegistry.OwnedOutput out=f.output(bad,1);assertThrows(IOException.class,()->out.write(7));out.close();assertThrows(SecurityException.class,()->exact(out,copy(new byte[0])));}
 @Test public void unknownCloseSpentOnceNotFakeReturned()throws Throwable{F f=new F();AtomicInteger closes=new AtomicInteger();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(){public void close()throws IOException{closes.incrementAndGet();throw new IOException("synthetic");}},1);out.write(7);assertThrows(IOException.class,out::close);out.close();assertEquals(1,closes.get());assertThrows(SecurityException.class,()->exact(out,copy(new byte[]{7})));}
 @Test public void zeroLengthSourceHasRealCloseAndEmptyDigest()throws Throwable{F f=new F();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(),0);assertThrows(SecurityException.class,()->exact(out,copy(new byte[0])));out.close();exact(out,copy(new byte[0]));}
 @Test public void boundStopsBeforeExternalWrite()throws Exception{F f=new F();ByteArrayOutputStream memory=new ByteArrayOutputStream();SaveTargetRegistry.OwnedOutput out=f.output(memory,1);assertThrows(IOException.class,()->out.write(new byte[]{1,2}));assertEquals(0,memory.size());out.close();}
 @Test public void sourceRetirementDuringWriteDoesNotPermitReceipt()throws Throwable{F f=new F();ByteArrayOutputStream memory=new ByteArrayOutputStream(){public synchronized void write(byte[] b,int o,int n){super.write(b,o,n);f.view.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));}};SaveTargetRegistry.OwnedOutput out=f.output(memory,1);assertThrows(SecurityException.class,()->out.write(8));assertEquals(1,memory.size());out.close();assertThrows(SecurityException.class,()->exact(out,copy(new byte[]{8})));}
 @Test public void noWritesOrFlushAfterClose()throws Exception{F f=new F();SaveTargetRegistry.OwnedOutput out=f.output(new ByteArrayOutputStream(),1);out.close();assertThrows(IOException.class,()->out.write(1));assertThrows(IOException.class,out::flush);}
}
